import {PREFERENCE_DEFINITIONS,PREFERENCE_APPLICABILITY,preferenceApplies} from './schema.js';
export {PREFERENCE_DEFINITIONS,PREFERENCE_APPLICABILITY,preferenceApplies};
export const SCOPED_PREFERENCES_OWNER='ScopedPreferencesOwner';
export const SCOPED_PREFERENCES_CONTRACT=Object.freeze({id:SCOPED_PREFERENCES_OWNER,version:'1.0.0',storageKey:'cep-foundation.preferences.v1',applicabilityPolicyTag:'family-filter-v1'});
const clone=value=>structuredClone(value);
const scopePattern=/^(global|workspace:[\w-]+|surface:[\w-]+|view:[\w-]+:[\w-]+|component:[\w-]+:[\w-]+)$/;

/** Canonical Global owner for preference scope, applicability, precedence and truthful persistence. */
export class ScopedPreferencesOwner {
  constructor(storage=null,context={workspace:'W02',surface:'library',view:'main',component:'workspace',family:'structured'}){this.storage=storage;this.context={workspace:'W02',surface:'library',view:'main',component:'workspace',family:'structured',...context};this.overrides={};this.error=null;this.persistence={available:!!storage&&typeof storage.getItem==='function'&&typeof storage.setItem==='function',durable:false,lastOperation:'init',error:null};this.load();}
  scopes(){const c=this.context;return ['global',`workspace:${c.workspace}`,`surface:${c.surface}`,`view:${c.surface}:${c.view}`,`component:${c.surface}:${c.component}`,'session'];}
  isApplicable(key,context=this.context){if(!PREFERENCE_DEFINITIONS[key])throw Error('UNKNOWN_PREFERENCE:'+key);return preferenceApplies(key,context.family||'global');}
  applicability(key,context=this.context){return {key,family:context.family||'global',applicable:this.isApplicable(key,context),families:[...(PREFERENCE_APPLICABILITY[key]||[])],policyTag:SCOPED_PREFERENCES_CONTRACT.applicabilityPolicyTag};}
  validate(key,value){const d=PREFERENCE_DEFINITIONS[key];if(!d)throw Error('UNKNOWN_PREFERENCE:'+key);if(d.values&&!d.values.includes(value))throw Error('INVALID_PREFERENCE:'+key);if(typeof d.safeDefault==='boolean'&&typeof value!=='boolean')throw Error('INVALID_BOOLEAN:'+key);if(typeof d.safeDefault==='number'&&(!Number.isFinite(value)||value<d.min||value>d.max))throw Error('OUT_OF_RANGE:'+key);return value;}
  set(key,value,scope='global'){if(!this.scopes().includes(scope))throw Error('INVALID_SCOPE');if(!this.isApplicable(key))throw Error('PREFERENCE_NOT_APPLICABLE:'+key+':'+this.context.family);this.validate(key,value);(this.overrides[scope]??={})[key]=value;return this.save();}
  reset(key,scope='global'){if(!this.scopes().includes(scope))throw Error('INVALID_SCOPE');if(this.overrides[scope])delete this.overrides[scope][key];return this.save();}
  resolve(key,effective){const d=PREFERENCE_DEFINITIONS[key];if(!d)throw Error('UNKNOWN_PREFERENCE:'+key);const applicable=this.isApplicable(key);let preferredValue=d.safeDefault,sourceScope='default';if(applicable)for(const scope of this.scopes())if(Object.hasOwn(this.overrides[scope]||{},key)){preferredValue=this.overrides[scope][key];sourceScope=scope}return {key,safeDefault:d.safeDefault,preferredValue,effectiveValue:effective??preferredValue,sourceScope,isOverridden:sourceScope!=='default',applicable,applicability:applicable?'presentation':'not-applicable',applicabilityOwner:SCOPED_PREFERENCES_OWNER,persistenceOwner:SCOPED_PREFERENCES_OWNER,resetTarget:sourceScope};}
  values({applicableOnly=false}={}){const keys=Object.keys(PREFERENCE_DEFINITIONS).filter(key=>!applicableOnly||this.isApplicable(key));return Object.fromEntries(keys.map(key=>[key,this.resolve(key).preferredValue]));}
  export(){return {schemaVersion:1,kind:'cep-foundation-preferences',overrides:clone(Object.fromEntries(Object.entries(this.overrides).filter(([scope])=>scope!=='session')))};}
  import(data){if(data?.schemaVersion!==1||data.kind!=='cep-foundation-preferences'||!data.overrides||typeof data.overrides!=='object')throw Error('UNSUPPORTED_PREFERENCE_SCHEMA');const next={};for(const [scope,values]of Object.entries(data.overrides)){if(!scopePattern.test(scope))throw Error('INVALID_SCOPE');if(!values||typeof values!=='object'||Array.isArray(values))throw Error('INVALID_SCOPE_VALUES:'+scope);next[scope]={};for(const [key,value]of Object.entries(values)){this.validate(key,value);next[scope][key]=value}}this.overrides=next;return true;}
  load(){if(!this.persistence.available){this.persistence={available:false,durable:false,lastOperation:'load',error:'STORAGE_UNAVAILABLE'};return {ok:false,durable:false,code:'STORAGE_UNAVAILABLE'};}try{const raw=this.storage.getItem(SCOPED_PREFERENCES_CONTRACT.storageKey);if(raw){const before=this.overrides;try{this.import(JSON.parse(raw));}catch(error){this.overrides=before;throw error;}}this.error=null;this.persistence={available:true,durable:true,lastOperation:'load',error:null};return {ok:true,durable:true,code:'LOADED'};}catch(error){this.error=String(error);this.persistence={available:true,durable:false,lastOperation:'load',error:this.error};return {ok:false,durable:false,code:'STORAGE_READ_FAILED',error:this.error};}}
  save(){if(!this.persistence.available){this.error='STORAGE_UNAVAILABLE';this.persistence={available:false,durable:false,lastOperation:'save',error:this.error};return {ok:false,durable:false,code:'STORAGE_UNAVAILABLE',error:this.error};}try{this.storage.setItem(SCOPED_PREFERENCES_CONTRACT.storageKey,JSON.stringify(this.export()));this.error=null;this.persistence={available:true,durable:true,lastOperation:'save',error:null};return {ok:true,durable:true,code:'PERSISTED'};}catch(error){this.error=String(error);this.persistence={available:true,durable:false,lastOperation:'save',error:this.error};return {ok:false,durable:false,code:'STORAGE_WRITE_FAILED',error:this.error};}}
  storageStatus(){return {...this.persistence};}
}
